// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Keep domain wide but avoid weird canonical zero-address pruning
        // We allow any address (EOA) as fuzz input
        // Make caller the contract deployer/owner by default (setUp deployed c so msg.sender in constructor isn't used)
        // Use transferOwnership if caller is owner: first ensure we are owner by calling transferOwnership from owner.

        // Determine current owner via public getter
        address initialOwner = c.owner();

        // Only the owner can call transferOwnership. Ensure we call as owner.
        // If the test runner isn't the owner, attempt to renounce/transfer via initialOwner
        // If initialOwner is address(this) (the test contract), we can call directly. Otherwise, prank as initialOwner.

        if (initialOwner == address(this)) {
            // we are owner, proceed
            c.transferOwnership(newOwner);
        } else {
            vm.prank(initialOwner);
            c.transferOwnership(newOwner);
        }

        // After transferOwnership, the contract's owner() MUST return the stored _owner value which equals newOwner
        // This is a universal property for reference; mutant changes returned behavior in some cases so fuzz will find mismatch
        address observed = c.owner();

        // Single assertion reading c's public getter
        assertTrue(observed == newOwner);
    }
}

