pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // General rule: after calling transferOwnership(newOwner), the public owner() getter must return exactly newOwner.
    // We fuzz the newOwner value (including address(0)). The reference implementation always returns the stored owner value;
    // the mutant sometimes returns address(0) instead and will thus be caught when newOwner == address(0).
    function testFuzz_property(address newOwner) public {
        // keep domain wide; no restrictive vm.assume so fuzzer may choose address(0)

        // transfer ownership to the fuzzed address (caller must be owner). The freshly deployed contract sets owner to msg.sender in initializer
        // so set the caller to the initial owner (this contract's test address)
        vm.prank(address(this));
        // call transferOwnership on c to set the stored owner to newOwner
        c.transferOwnership(newOwner);

        // read owner() from contract and assert it equals the value we set
        address reported = c.owner();

        // Single assertion: owner() must equal the stored owner we set via transferOwnership(newOwner)
        assertTrue(reported == newOwner);
    }
}

