pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the newOwner address; for any newOwner, after calling transferOwnership(newOwner)
    // the owner() getter must return exactly newOwner. The mutant that alters owner()
    // to special-case address(0) will still return address(0) for newOwner==address(0)
    // (matching stored value) but our general property ensures the getter reflects the stored value
    // for every fuzzed input; the mutant will diverge for some inputs the fuzzer can find
    function testFuzz_property(address newOwner) public {
        // keep domain wide; no tight assumptions so fuzzer can find failing case
        // perform the call as the current owner: on initialization, __Ownable_init sets owner to address(this) via initializer
        // but our c was constructed via new C() (not initialize), so owner is zero initially; transferOwnership is onlyOwner
        // So we need to set up ownership by calling __Ownable_init flow: call initialize to set owner to this test contract

        // Prepare parameters required by initialize (we can pass zero addresses or minimal mocks because initialize stores addresses)
        IERC20 dummyToken = IERC20(address(0));
        IRewardRouterV2 dummyRouter = IRewardRouterV2(address(0));
        IGlpManager dummyManager = IGlpManager(address(0));
        address dummyJunior = address(0);
        address keeper = address(this);

        // call initialize as the deploying tx (we are the caller) to become owner
        c.initialize(dummyToken, dummyToken, dummyRouter, dummyManager, dummyJunior, keeper);

        // Now msg.sender (this test contract) is owner and can transfer ownership
        c.transferOwnership(newOwner);

        // Exactly one observation: owner() must equal the stored owner which should be newOwner
        // We read via the public owner() getter
        assertTrue(c.owner() == newOwner);
    }
}

// Minimal interfaces used in the test; redeclare to satisfy compiler
interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}
interface IRewardRouterV2 { function mintAndStakeGlp(address token, uint256 amount, uint256 minUsdg, uint256 minGlp) external returns (uint256); }
interface IGlpManager { function vault() external view returns (address); }

