pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameter is the newOwner we will set via transferOwnership
    function testFuzz_property(address newOwner) public {
        // keep domain wide but avoid very constrained values
        // call transferOwnership as the contract owner (set in initializer via __Ownable_init => owner is address(this))
        // need to perform owner-only call: transferOwnership is onlyOwner. The deploying test contract is not owner.
        // However, C.__Ownable_init sets owner to msg.sender when initialize is called. Since we didn't call initialize,
        // owner() is zero initially. To become owner we can call c.initialize(...) but it is external initializer and will set owner to msg.sender.
        // We must call initialize with proper typed dummy arguments. Provide addresses cast via interfaces by deploying small helpers.

        // Deploy dummy contracts to satisfy types
        DummyERC20 token = new DummyERC20();
        DummyRouter router = new DummyRouter();
        DummyGlpManager gm = new DummyGlpManager();
        DummyJuniorVault djv = new DummyJuniorVault();

        // initialize will set owner to address(this)
        c.initialize(IERC20(address(token)), IERC20(address(token)), IRewardRouterV2(address(router)), IGlpManager(address(gm)), address(djv), address(this));

        // Now this test contract is owner and can call transferOwnership
        c.transferOwnership(newOwner);

        // The general property: after transferOwnership(newOwner), owner() must return exactly the stored owner value (which is newOwner).
        // We observe owner() via the public getter. The mutant sometimes returns address(0) instead of the stored owner, so assert equality.
        address observed = c.owner();

        assertTrue(observed == newOwner);
    }
}

