pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract CallerHelper {
    C target;
    constructor(C _target) {
        target = _target;
    }
    function proxiedOwner() external view returns (address) {
        // call the target.owner() from this contract's context
        return target.owner();
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: the reference's owner() returns the stored owner (the deployer from initialization)
    // The mutant returning tx.origin will differ when owner() is invoked through another contract (tx.origin != intermediate contract address)
    function testFuzz_property(address caller) public {
        // keep caller as any address but avoid zero to be meaningful
        vm.assume(caller != address(0));

        // The contract was deployed in setUp() by this test contract (msg.sender == address(this)).
        // The Initializable initializer wasn't called, so owner() in reference should be address(0)
        // but per contract C logic __Ownable_init is called by initialize; since initialize wasn't called,
        // owner() should be the default _owner value. However the stable invariant we can assert for the reference
        // is: calling owner() directly from an EOA or this test returns the same value as calling owner() via an intermediate contract
        // for the correct implementation (owner() returns stored _owner), but for the mutant (owner() returns tx.origin)
        // the two will differ when proxied.

        // Deploy helper that calls owner() on c from its own context
        CallerHelper helper = new CallerHelper(c);

        // Call owner() directly (from this test contract)
        address directOwner = c.owner();

        // Call owner() via the helper contract (so msg.sender inside helper is helper, and tx.origin is this test contract)
        address proxiedOwner = helper.proxiedOwner();

        // The correct contract returns the same stored owner regardless of being called directly or via another contract.
        // The mutant that returns tx.origin will return different values when called via helper vs directly.
        assertTrue(directOwner == proxiedOwner);
    }
}

