pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Forwarder fw;

    function setUp() public {
        c = new C();
        fw = new Forwarder();
    }

    // The fuzz parameter is an address 'caller' which the fuzzer will vary.
    // We keep the domain wide but avoid the zero address for practicality.
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        // Ensure the caller has ETH so it can call through the forwarder if needed.
        vm.deal(caller, 1 ether);

        // 1) When caller calls owner() directly, tx.origin == msg.sender == caller.
        bool okDirect;
        address directOwner;
        vm.prank(caller);
        try c.owner() returns (address o) {
            okDirect = true;
            directOwner = o;
        } catch {
            okDirect = false;
        }

        // 2) When caller calls through the Forwarder, the forwarder will call c.owner().
        //    In that case tx.origin == caller, but msg.sender == address(forwarder).
        bool okForwarded;
        address forwardedOwner;
        // Ask the forwarder to forward a staticcall to c.owner() and return the decoded address.
        vm.prank(caller);
        try fw.forwardView(address(c), abi.encodeWithSignature("owner()")) returns (bytes memory ret) {
            // decode if call succeeded
            if (ret.length == 32) {
                forwardedOwner = abi.decode(ret, (address));
                okForwarded = true;
            } else {
                okForwarded = false;
            }
        } catch {
            okForwarded = false;
        }

        // The universal property we assert:
        // For any admissible caller, both the direct call and the forwarded call should succeed
        // and both must return the same owner address (the stored owner). The reference C
        // implementation always uses the stored owner and thus this holds for all callers; the
        // mutant that returns tx.origin will make the forwardedOwner == caller while directOwner == stored owner
        // for some caller, causing the assertion to fail.
        assertTrue(
            // both calls succeeded
            okDirect && okForwarded &&
            // and returned identical results
            directOwner == forwardedOwner
        );
    }
}

// Minimal forwarder that performs a call into target using the exact calldata provided
contract Forwarder {
    // perform a low-level call and return raw returndata
    function forwardView(address target, bytes calldata data) external returns (bytes memory) {
        (bool success, bytes memory ret) = target.call(data);
        require(success, "forwarded call failed");
        return ret;
    }
}

