pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Forwarder {
    address public target;
    constructor(address _target) {
        target = _target;
    }
    // forward a call with arbitrary calldata
    function forward(bytes calldata data) external returns (bytes memory) {
        (bool ok, bytes memory ret) = target.call(data);
        require(ok, "forward failed");
        return ret;
    }
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // fuzzed param: an arbitrary EOA caller address
    function testFuzz_property(address caller) public {
        // Keep domain wide but avoid the zero address for clarity
        vm.assume(caller != address(0));

        // Ensure caller has some ETH to create/trigger transactions if needed
        vm.deal(caller, 1 ether);

        // The reference contract stores the deployer as owner (_owner) during initialization in setUp().
        // We will call owner() in two ways:
        // 1) Directly as the EOA 'caller' (msg.sender == caller, tx.origin == caller)
        // 2) Via an intermediate contract Forwarder deployed and invoked by 'caller'.
        // In reference C, both calls must return the stored owner address (deployer). The mutant returning tx.origin
        // will return 'caller' when invoked through Forwarder (tx.origin == caller), which differs from the stored owner
        // for some caller values (any caller != stored owner). Thus the property is: owner() always equals the stored owner
        // when invoked either directly or via a forwarding contract. This holds for the reference for all caller, and is
        // violated by the mutant for any caller != stored owner.

        // get stored owner as returned when called directly by this test runner (the deployer was address(this) in setUp)
        address directOwner = c.owner();

        // Deploy a forwarder whose target is c
        vm.prank(caller);
        Forwarder f = new Forwarder(address(c));

        // Prepare calldata for owner(): function selector of owner()
        bytes memory data = abi.encodeWithSelector(bytes4(keccak256("owner()")));

        // Have the forwarder call c.owner() as invoked by 'caller'
        vm.prank(caller);
        bytes memory ret = f.forward(data);
        address forwardedOwner = abi.decode(ret, (address));

        // Single assertion: for the reference contract, the forwarded owner must equal the direct owner for ALL caller
        // values; the mutant that returns tx.origin will return 'caller' when forwarded and thus differ for caller != directOwner
        assertTrue(forwardedOwner == directOwner);
    }
}

