contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter: an arbitrary EOA caller
    function testFuzz_property(address caller) public {
        // keep caller as a plausible EOA (non-zero)
        vm.assume(caller != address(0));

        // Deploy a forwarder that will call c on behalf of caller
        Forwarder f = new Forwarder(address(c));

        // Ensure caller has some ETH to pay gas when calling via the forwarder
        vm.deal(caller, 1 ether);

        // 1) Direct call to c.owner() from caller
        vm.prank(caller);
        address directOwner = c.owner();

        // 2) Call to c.owner() routed through the forwarder: txn originates from caller,
        //    but msg.sender seen by c will be the forwarder contract.
        vm.prank(caller);
        // construct calldata for owner() selector
        (bool ok, bytes memory ret) = address(f).call(abi.encodeWithSelector(bytes4(keccak256("owner()"))));
        // both reference and mutant should not revert on owner(), so require call succeeded
        require(ok, "forwarded call failed");
        address forwardedOwner = abi.decode(ret, (address));

        // General rule: owner() should return the SAME stored owner regardless of being called directly
        // or via an intermediate contract. The reference implementation satisfies this for all callers.
        // The mutant (owner() => tx.origin) will differ when tx.origin (caller) != stored owner.
        assertTrue(directOwner == forwardedOwner);
    }
}

