pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: an EOA caller and an arbitrary nonzero gas-wasting value to keep fuzzer busy
    function testFuzz_property(address caller, uint256 junk) public {
        // keep caller as a non-zero address (EOA-like) and distinct from address(0)
        vm.assume(caller != address(0));
        // also avoid the trivial case where caller equals address(this) (not necessary but keeps variety)
        vm.assume(caller != address(this));

        // Deploy a small forwarder/proxy that will call c.owner() and return the result
        Forwarder f = new Forwarder();

        // Make the fuzzed EOA be funded so it can perform the call via the forwarder
        vm.deal(caller, 1 ether);

        // Have the EOA call the forwarder which will in turn call c.owner() using a call from the forwarder
        // We simulate the EOA initiating the tx by vm.prank(caller)
        vm.prank(caller);
        address returnedFromProxy = f.proxyCallOwner(address(c));

        // Also directly call owner() from the same EOA (direct call)
        vm.prank(caller);
        address returnedDirect = c.owner();

        // GENERAL RULE: In the reference contract, owner() always returns the stored owner (the deployer),
        // independent of whether the call is direct or proxied. Therefore both returnedDirect and returnedFromProxy
        // must equal the stored owner (which is the deployer: address(this) from setUp()).
        // We assert that the direct and proxied results are equal to each other and equal to the stored owner.
        // This will hold for the reference; the mutant (owner() -> tx.origin) will return caller for the proxied call,
        // which will differ from the stored owner and cause this assertion to fail for some fuzzed caller.

        address storedOwner = c.owner(); // direct view to obtain expected stored owner

        // Exactly one assertion as required
        assertTrue(returnedFromProxy == storedOwner && returnedDirect == storedOwner);
    }
}

contract Forwarder {
    // Calls owner() on target and returns the obtained address
    function proxyCallOwner(address target) external returns (address) {
        (bool ok, bytes memory res) = target.call(abi.encodeWithSignature("owner()"));
        require(ok, "call failed");
        return abi.decode(res, (address));
    }
}

