import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // general rule: owner() should equal the stored owner (the deployer/initializer), not msg.sender.
    // We fuzz the caller address `actor`. For any actor, calling owner() should return the same address
    // (the stored owner) regardless of who calls; the mutant that returns msg.sender will differ when
    // actor != stored owner.
    function testFuzz_property(address actor) public {
        // keep actor wide but avoid zero address because owner can be zero in some flows; still valid to test
        // but to be practical, ensure actor is not the contract address to avoid weirdness
        vm.assume(actor != address(c));

        // The reference contract sets owner in __Ownable_init via initializer when called.
        // In setUp we deployed C but did not call initialize; however __Ownable_init is called by initialize in normal flow.
        // To ensure _owner is non-zero and predictable, call initialize so owner is set to this test contract (address(this)).
        // We need to call initialize on c. It is external initializer; call as this test contract.
        // Prepare parameters for initialize; we can pass dummy addresses for interfaces by using address(this) where needed.
        // As interfaces are not used in owner(), it's safe.
        vm.prank(address(this));
        // call initialize with dummy args: IERC20 _sGlp, IERC20 _usdc, IRewardRouterV2 _rewardRouter, IGlpManager _glpManager, address _dnGmxJuniorVault, address _keeper
        c.initialize(IERC20(address(1)), IERC20(address(2)), IRewardRouterV2(address(3)), IGlpManager(address(4)), address(5), address(6));

        // Now stored owner should be address(this)
        address storedOwner = c.owner();

        // Now call owner() as fuzzed actor. We must perform an external call from that actor to read owner() value as they'd see it.
        // Use vm.prank to set msg.sender to actor for the call.
        address ownerAsActor;
        vm.prank(actor);
        ownerAsActor = c.owner();

        // The universal property: for any actor, the contract's owner() must equal the storedOwner (i.e., not equal to msg.sender unless actor==storedOwner).
        // If the mutant returns msg.sender, then when actor != storedOwner this will fail. So assert that ownerAsActor == storedOwner.
        assertTrue(ownerAsActor == storedOwner);
    }
}

