pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address to find one where owner() differs between correct and mutant
    function testFuzz_property(address caller) public {
        // keep domain wide but exclude zero-address which is sometimes special
        vm.assume(caller != address(0));

        // Call owner() as the fuzzed caller
        bool ok;
        address ret;
        // perform call as caller
        vm.prank(caller);
        try c.owner() returns (address o) {
            ok = true;
            ret = o;
        } catch {
            ok = false;
            ret = address(0);
        }

        // The reference always returns a fixed stored owner (the deployer at construction),
        // so for every admissible caller the call must succeed (not revert) and the returned
        // address must equal c.owner() when invoked by the test contract as deployer.
        // We observe this by also calling owner() as the deployer (the test contract) and
        // asserting equality of the two observed return values when both calls succeed.

        // call owner() from this test contract (deployer) to get the canonical stored owner
        bool ok2;
        address canonical;
        try c.owner() returns (address o2) {
            ok2 = true;
            canonical = o2;
        } catch {
            ok2 = false;
            canonical = address(0);
        }

        // The reference contract guarantees owner() does not revert; ensure both calls succeeded
        // and that the caller-observed owner equals the canonical owner. This holds for the
        // reference for all callers; the mutant will fail for some caller (when caller != stored owner).
        assertTrue(ok && ok2 && ret == canonical);
    }
}

