import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    OwnerCaller ownerCaller;

    function setUp() public {
        c = new C();
        ownerCaller = new OwnerCaller();
    }

    // fuzzed params: newOwner (address) and ownerEoa (address used as EOA that will be tx.origin)
    function testFuzz_property(address newOwner, address ownerEoa) public {
        vm.assume(newOwner != address(0));
        vm.assume(ownerEoa != address(0));
        // ensure ownerEoa is an EOA for the test (fuzzer may give contracts, but we'll treat any address as EOA by using prank)

        // Make ownerEoa the owner by calling initialize via ownerEoa
        // C has initializer; call initialize with simple dummy addresses (using address(c) for some args is fine)
        // We need to craft parameters; use address(0x100) as dummy token addresses etc.
        vm.prank(ownerEoa);
        c.initialize(IERC20(address(0x100)), IERC20(address(0x101)), IRewardRouterV2(address(0x102)), IGlpManager(address(0x103)), address(0x104), ownerEoa);

        // Now call transferOwnership(newOwner) through a contract (ownerCaller) so msg.sender == address(ownerCaller)
        // but tx.origin == ownerEoa (because we prank ownerEoa for the outer call to the contract)
        vm.prank(ownerEoa);
        bool ok;
        try ownerCaller.callTransferOwnership(address(c), newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: when the current owner (here ownerCaller contract acted via tx.origin == ownerEoa)
        // calls transferOwnership through a contract, the reference implementation (which checks msg.sender==owner)
        // will allow the call because the contract ownerCaller has been set as owner (we set owner to ownerEoa then make ownerCaller become owner by transfer via ownerEoa?)
        // To ensure ownerCaller is the direct caller recognized as owner by contract c, we first transfer ownership to ownerCaller via ownerEoa.
    }
}

// Minimal helper contract that will be used to call transferOwnership on target C
contract OwnerCaller {
    function callTransferOwnership(address target, address newOwner) external {
        C(target).transferOwnership(newOwner);
    }
}

