pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract CallerContract {
    // will call transferOwnership on target
    function callTransferOwnership(C target, address newOwner) external returns (bool ok) {
        try target.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: owner EOA, a contract caller that will be set as owner, and a newOwner address
    function testFuzz_property(address ownerEoa, address contractCallerSalt, address newOwner) public {
        // keep addresses non-zero and distinct enough
        vm.assume(ownerEoa != address(0));
        vm.assume(newOwner != address(0));
        // derive a contract deployer address from salt to vary contract address
        // we deploy the CallerContract from an EOA derived from ownerEoa to simulate ownership being transferred to a contract

        // 1) set the initial owner to ownerEoa by calling initialize and then transferring ownership from deployer
        // initialize requires calling initializer; C.__Ownable_init sets owner to msg.sender — current deployer is this test contract
        // so we first make this test contract the owner (it already is via new C()), then transfer ownership to ownerEoa

        // ensure ownerEoa is an EOA by making no code at that address (fuzzed addresses in tests are EOAs)
        // transfer ownership from test contract (current owner) to ownerEoa
        c.transferOwnership(ownerEoa);
        // now owner() == ownerEoa
        assert(c.owner() == ownerEoa);

        // 2) from ownerEoa, transfer ownership to a contract (the contractCaller). We need to simulate ownerEoa calling a contract creation
        // Forge cannot originate transactions from arbitrary fuzzed address to deploy a contract, but we can prank as ownerEoa to deploy the CallerContract
        vm.prank(ownerEoa);
        CallerContract contractCaller = new CallerContract();

        // Now ownerEoa (msg.sender) deployed contractCaller; still ownerEoa is owner of c
        // Owner (ownerEoa) calls transferOwnership(contractCaller) to make the contract the owner
        vm.prank(ownerEoa);
        c.transferOwnership(address(contractCaller));
        // After this, reference contract should set owner to the contract address
        assert(c.owner() == address(contractCaller));

        // 3) Now we simulate calling transferOwnership(newOwner) through the contractCaller.
        // According to the reference C, onlyOwner checks msg.sender == owner; since the call originates from contractCaller, msg.sender == contractCaller and it should succeed.
        // The mutant additionally checks tx.origin == owner; when the contract is calling, tx.origin will be the original EOA that invoked contractCaller — in our test we are an arbitrary EOA when sending the transaction below.

        // We now have two different callers scenarios to fuzz: we will vary the EOA that sends the tx to contractCaller by using contractCallerSalt to derive an EOA
        // Use vm.prank to set tx.origin (the immediate tx.origin will be the EOA we prank as when calling contractCaller.callTransferOwnership)
        address txOrigin = address(uint160(uint256(keccak256(abi.encodePacked(contractCallerSalt, block.number, block.timestamp)))));
        if (txOrigin == address(0)) txOrigin = address(1);

        // Ensure txOrigin is not equal to address(contractCaller) to represent typical externally owned origin
        vm.prank(txOrigin);
        bool ok = contractCaller.callTransferOwnership(c, newOwner);

        // GENERAL RULE ASSERTION: On the reference contract, when the current owner is a contract (contractCaller), calling transferOwnership(newOwner) via that contract should succeed (permission is based on msg.sender == owner), so callTransferOwnership returns true.
        // The mutant that checks tx.origin may fail for some txOrigin values (when tx.origin != owner) causing ok==false. We assert the reference behaviour (ok==true).
        assertTrue(ok, "reference should allow contract owner (msg.sender) to call transferOwnership via the contract");
    }
}

