pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // General rule: For any caller and timing, the reference contract's paused() reflects the internal _paused flag;
    // specifically, when the keeper calls unpauseDeposit (which calls _unpause) the contract becomes unpaused and
    // paused() must return false. The mutant that forces paused() to always return true will break this.
    // We fuzz the keeper address to avoid hard-coding an actor.
    function testFuzz_property(address keeperAddr) public {
        // fuzzed keeper must be non-zero
        vm.assume(keeperAddr != address(0));

        // initialize contract with arbitrary parameters; many can be zero addresses as long as initializer runs
        // We call initialize via its external initializer; it will set keeper to vaultBatchingManager's keeper param
        // Use prank from an EOA to be initializer caller
        vm.prank(address(this));
        // Provide dummy parameters; types must match
        // (IERC20 _sGlp, IERC20 _usdc, IRewardRouterV2 _rewardRouter, IGlpManager _glpManager, address _dnGmxJuniorVault, address _keeper)
        c.initialize(IERC20(address(0)), IERC20(address(0)), IRewardRouterV2(address(0)), IGlpManager(address(0)), address(0), keeperAddr);

        // At this point __Pausable_init sets _paused = false. The keeper can call pauseDeposit to pause.
        // First ensure initial paused() reflects unpaused state (should be false on reference).
        bool ok;
        try c.paused() returns (bool v) {
            ok = v == false || v == true; // simply ensures call succeeded
        } catch {
            ok = false;
        }
        // ok should be true (call succeeded). This is just setup; now simulate keeper pausing and unpausing behavior.

        // The keeper (keeperAddr) calls pauseDeposit -> sets _paused = true
        vm.prank(keeperAddr);
        c.pauseDeposit();

        // After pausing, paused() must return true on reference
        bool pausedAfterPause;
        try c.paused() returns (bool v) { pausedAfterPause = v; } catch { pausedAfterPause = false; }
        // Now unpauseDeposit by keeper to set _paused = false
        vm.prank(keeperAddr);
        c.unpauseDeposit();

        // Single assertion: after unpauseDeposit by the keeper, the reference contract's paused() must be false.
        // The mutant that always returns true will fail this assertion for some fuzzed keeperAddr (indeed any valid keeperAddr).
        bool pausedAfterUnpause;
        try c.paused() returns (bool v) { pausedAfterUnpause = v; } catch { pausedAfterUnpause = true; }

        assertTrue(pausedAfterUnpause == false);
    }
}

