import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address keeper = address(0xBEEF);
    address owner = address(0xCAFE);

    function setUp() public {
        c = new C();
        // initialize with dummy params: C.initialize expects several addresses via IERC20/IGlpManager etc.
        // We cannot call initialize because interfaces/types live in C; but constructor isn't used.
        // Instead, we will rely on pause/unpause functions which are protected by onlyKeeper; set keeper by calling setKeeper as owner.
        // We must be the owner to call setKeeper. The contract uses OwnableUpgradeable and initialize to set owner on initializer,
        // but since initialize wasn't called, owner is zero; however __Ownable_init sets owner to msg.sender only during initialize.
        // To work around, we use low-level call to set keeper via storage is not allowed. Instead we will exploit public setKeeper onlyOwner —
        // So we will call c.setKeeper via the account that is currently owner. In absence of initialize, owner is address(0), and onlyOwner would fail.
        // To avoid relying on initialize, we instead use try/catch around paused() only and use external calls to pause/unpause via keeper-restricted functions using vm.prank to simulate keeper.
        // However pauseDeposit/unpauseDeposit are onlyKeeper — calling them from keeper address will fail because keeper storage is default zero. So we set keeper by calling setKeeper from owner.
        // Since owner is zero, we can impersonate address(0) using vm.prank; address(0) is not a real account but vm.prank supports it.
        vm.prank(address(0));
        // setKeeper will revert if not owner; but owner() likely returns address(0) initially because __Ownable_init not called; thus this vm.prank will succeed as owner.
        c.setKeeper(keeper);
    }

    // fuzz the decision whether to call pauseDeposit or unpauseDeposit (as keeper) and then assert paused() matches expectation
    function testFuzz_property(bool startPaused, bool callUnpause) public {
        // startPaused: if true, we first have keeper pause via pauseDeposit(); otherwise ensure not paused by attempting unpauseDeposit (may revert if not paused)
        // Make keeper act
        vm.prank(keeper);
        if (startPaused) {
            // pauseDeposit will set paused state
            try c.pauseDeposit() {
            } catch {
                // if it reverts, ignore — we'll rely on paused() call to observe behavior
            }
        } else {
            // try to unpause to ensure not paused; if it reverts (not allowed), ignore
            try c.unpauseDeposit() {
            } catch {
            }
        }

        // Now optionally call unpause (toggle to not paused) depending on callUnpause
        if (callUnpause) {
            vm.prank(keeper);
            try c.unpauseDeposit() {
            } catch {
            }
        }

        // Determine expected paused state using the sequence we executed:
        // Conservative approach: query both pause and unpause actions' intended effect by re-invoking unprivileged calls isn't possible; instead derive expectedPaused:
        // If callUnpause is true -> expected not paused (false). Else if startPaused true and callUnpause false -> expected paused (true). Else expected not paused (false).
        bool expectedPaused;
        if (callUnpause) expectedPaused = false;
        else if (startPaused) expectedPaused = true;
        else expectedPaused = false;

        // Now call paused() and assert it equals expectedPaused. Use try/catch to convert reverts into failure (ok=false).
        bool ok;
        try c.paused() returns (bool p) {
            ok = (p == expectedPaused);
        } catch {
            ok = false;
        }

        // Single assertion: reference C should always have ok==true for all inputs; mutant that forces paused() to always return true will make ok==false
        assertTrue(ok);
    }
}

