    // The mutant changed behavior for newKeeper == address(0): it reverts/blocks or requires non-zero, so behavior differs.
    function testFuzz_property(address newKeeper) public {
        // owner is the deployer (this contract). Call as owner.
        // ensure newKeeper is any address (including zero) to let fuzzer find differing behavior
        bool ok;
        vm.prank(address(this));
        try c.setKeeper(newKeeper) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract allows setting keeper to any address (including zero) by the owner,
        // so if the call succeeded, keeper must equal the provided address; if the call reverted, keeper remains previous value.
        // We assert the property that if the call succeeded then c.keeper() == newKeeper.
